631	    /**
632	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes
633	     * and brackets are stripped. When the number already carries a leading {@code '+'}
634	     * and country code these are kept; a number written in national trunk form (a leading
635	     * {@code '0'}) is treated as Australian, so the {@code '0'} is dropped and country code
636	     * {@code '+61'} prepended; any other bare number is treated as a NANP number and country
637	     * code {@code '+1'} is prepended. The resulting number must have between 8 and 15 digits
638	     * after the {@code '+'}, and its national-number length must be valid for the detected
639	     * country code (see {@link #hasValidNationalLength}).
640	     *
641	     * @param telephone the raw telephone value supplied by the client
642	     * @return the E.164 telephone (e.g. {@code +61412345678}), or {@code null} when it
643	     *         cannot form a valid E.164 number (signalling a 400 Bad Request)
644	     */
645	    private static String toE164(String telephone) {
646	        if (telephone == null) {
647	            return null;
648	        }
649	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
650	        String digits;
651	        if (cleaned.startsWith("+")) {
652	            digits = cleaned.substring(1);
653	        } else if (cleaned.startsWith("0")) {
654	            digits = "61" + cleaned.substring(1);
655	        } else {
656	            digits = "1" + cleaned;
657	        }
658	        if (!digits.matches("[0-9]{8,15}")) {
659	            return null;
660	        }
661	        if (!hasValidNationalLength(digits)) {
662	            return null;
663	        }
664	        return "+" + digits;
665	    }
666	
667	    /**
668	     * Validates the national-number length of an E.164 digit string against its country
669	     * code: Australia ({@code +61}) requires exactly 9 national digits and the NANP
670	     * ({@code +1}) requires exactly 10. Numbers under any other country code are not
671	     * length-checked here — only the general 8-to-15-digit E.164 bound applies to them.
672	     *
673	     * @param digits the E.164 digits (without the leading {@code '+'})
674	     * @return {@code true} when the national-number length is valid for the country code
675	     */
676	    private static boolean hasValidNationalLength(String digits) {
677	        if (digits.startsWith("61")) {
678	            return digits.length() - 2 == 9;
679	        }
680	        if (digits.startsWith("1")) {
681	            return digits.length() - 1 == 10;
682	        }
683	        return true;
684	    }
685	
686	    /**
687	     * Inclusive 4-digit postcode ranges permitted for each canonical region: NSW 2000-2099,
688	     * VIC 3000-3099 and QLD 4000-4099. A region absent from this table (e.g. the {@code
689	     * "UNKNOWN"} derived for a city with no known region) imposes no range restriction.
690	     */
691	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
692	        "NSW", new int[] {2000, 2099},
693	        "VIC", new int[] {3000, 3099},
694	        "QLD", new int[] {4000, 4099});
695	
696	    /**
697	     * Validates an owner's postcode for creation. A postcode is only ever validated when
